    id: 'dia-sap-denial-2009',
    cls: 'document',
    label: 'DIA Info Memo U-09-2660 — denial of restricted SAP for AAWSAP (13 Nov 2009)',
    cluster: 'other',
    sub: 'correspondence',
    desc: 'DIA\'s response to USD(I) Special Programs declining to establish a restricted SAP/ACCM for the AAWSAP contract.',
    tier: 'C',
    C: 0,
    A: 0,
    D: 0,
    dateStart: null,
